figure %[output:555f835d]
scatter(dataset_combined.dV_lambert ./ dataset_combined.dV_max, dataset_combined.dV_ratio) %[output:555f835d]
%%

unique(dataset_combined.dV_max) %[output:226cc106]
%%
fitResult_x = {};
%%
h = histfit(dataset_combined.dV_lambert ./ dataset_combined.dV_max, 100, "normal"); %[output:19dcc1c2]
fitResult_dV_lambert = fitdist(dataset_combined.dV_lambert' ./ dataset_combined.dV_max', "Normal") % Fit the model to the data %[output:90663d33]
%%
histfit(dataset_combined.v1_ast(3, :) - dataset_combined.v1_lambert(3, :), 100, "normal") %[output:11aaaf2e]
fitResult_vdiff{1}{1} = fitdist((dataset_combined.v1_ast(1, :)' - dataset_combined.v1_lambert(1, :)') ./ dataset_combined.dV_max', "Normal");
fitResult_vdiff{1}{2} = fitdist((dataset_combined.v2_ast(1, :)' - dataset_combined.v2_lambert(1, :)') ./ dataset_combined.dV_max', "Normal");
fitResult_vdiff{2}{1} = fitdist((dataset_combined.v1_ast(2, :)' - dataset_combined.v1_lambert(2, :)') ./ dataset_combined.dV_max', "Normal");
fitResult_vdiff{2}{2} = fitdist((dataset_combined.v2_ast(2, :)' - dataset_combined.v2_lambert(2, :)') ./ dataset_combined.dV_max', "Normal");
fitResult_vdiff{3}{1} = fitdist((dataset_combined.v1_ast(3, :)' - dataset_combined.v1_lambert(3, :)') ./ dataset_combined.dV_max', "Normal");
fitResult_vdiff{3}{2} = fitdist((dataset_combined.v2_ast(3, :)' - dataset_combined.v2_lambert(3, :)') ./ dataset_combined.dV_max', "Normal");

histfit((dataset_combined.v2_ast(3, :) - dataset_combined.v2_lambert(3, :)) ./ dataset_combined.dV_max, 100, "normal") %[output:8b1ee128]
